import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { brandId, toComment, toUser } from "./_mappers";

/**
 * Distinct authors of comments that are still on the issue. Replies are
 * comments, so they count; a soft-deleted comment does not.
 */
export async function listCommentAuthorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ authorId: comments.authorId })
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          livePredicate(comments.archivedAt, {}),
        ),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.authorId));
}

export async function countComments(

  return commentRepo.listThread(orgId, issueId);
}

/**
 * Everyone still in the organization who has a stake in the issue: its
 * author, its current assignee, and the authors of comments that have not
 * been deleted. A person is listed once. Removed members are left out.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthorIds = await commentRepo.listCommentAuthorIds(
    orgId,
    issueId,
  );

  const candidates: UserId[] = [];
  const seen = new Set<string>();
  const push = (userId: UserId | null) => {
    if (userId === null || seen.has(userId)) return;
    seen.add(userId);
    candidates.push(userId);
  };

  push(issue.authorId);
  push(issue.assigneeId);
  for (const userId of commentAuthorIds) push(userId);

  const memberships = await Promise.all(
    candidates.map((userId) => memberRepo.findMember(orgId, userId)),
  );

  return candidates.filter((_, index) => memberships[index]?.status === "active");
}

